<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Image Rotator Online','description'=>'Rotate images by 90, 180 or 270 degrees in your browser.','url'=>'https://smarttoolz.in/tools/image-rotate/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Image Rotator</h1><p>Rotate an image and download it.</p></section><section class="tool-workspace"><div class="tool-panel"><input id="f" type="file" accept="image/*"><select id="r"><option value="90">90°</option><option value="180">180°</option><option value="270">270°</option></select><button id="go" class="tool-btn">Rotate</button><a id="d" class="tool-btn" hidden download="rotated.png">Download</a></div></section></main><script>go.onclick=()=>{let f=document.getElementById('f').files[0];if(!f)return;let i=new Image;i.onload=()=>{let z=+r.value*Math.PI/180,c=document.createElement('canvas'),w=i.width,h=i.height;if(+r.value%180)c.width=h,c.height=w;else c.width=w,c.height=h;let x=c.getContext('2d');x.translate(c.width/2,c.height/2);x.rotate(z);x.drawImage(i,-w/2,-h/2);c.toBlob(b=>{d.href=URL.createObjectURL(b);d.hidden=false},'image/png')};i.src=URL.createObjectURL(f)}</script><?php smarttoolz_tool_page_end(); ?>